H.background();
const w = H.W;
const Ka = Math.max(1e-10, P.Ka);
const c = Math.max(1e-4, P.conc);
const x = (-Ka + Math.sqrt(Ka * Ka + 4 * Ka * c)) / 2;
const pH = -Math.log10(Math.max(1e-14, x));
const pct = (x / c) * 100;
const grow = 0.5 + 0.5 * Math.sin(t * 0.7);
const baseY = 470, maxH = 320;
const HA = c - x, prod = x;
const scaleV = maxH / c;
const bx1 = 200, bx2 = 420, bx3 = 640, bw = 120;
const hHA = HA * scaleV, hPr = prod * scaleV;
H.rect(bx1, baseY - hHA, bw, hHA, { fill: H.colors.accent, radius: 4 });
H.rect(bx2, baseY - hPr * grow, bw, hPr * grow, { fill: H.colors.warn, radius: 4 });
H.rect(bx3, baseY - hPr * grow, bw, hPr * grow, { fill: H.colors.good, radius: 4 });
H.line(140, baseY, 800, baseY, { color: H.colors.axis, width: 2 });
H.text("HA", bx1 + bw / 2 - 10, baseY + 20, { color: H.colors.sub, size: 13 });
H.text("H+", bx2 + bw / 2 - 10, baseY + 20, { color: H.colors.sub, size: 13 });
H.text("A-", bx3 + bw / 2 - 8, baseY + 20, { color: H.colors.sub, size: 13 });
H.text("Weak acid: Ka = x^2/(C - x),  x = [H+]", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Ka = " + Ka.toExponential(2) + "    C = " + c.toFixed(3) + " M", 24, 52, { color: H.colors.sub, size: 13 });
H.text("[H+] = " + x.toExponential(2) + " M   pH = " + pH.toFixed(2), 24, 74, { color: H.colors.good, size: 13 });
H.text("% ionization = " + pct.toFixed(2) + " %", 24, 96, { color: H.colors.accent2, size: 13 });
H.legend([{ label: "HA remaining", color: H.colors.accent }, { label: "H+ formed", color: H.colors.warn }, { label: "A- formed", color: H.colors.good }], w - 200, 28);
